        frame %= duration;
        if (frame < 0) {
            frame += duration;
        }
        if (frame == 0) {
            frame = duration;
        }
    } else {
        pingpong_duration = (duration * 2) - 2;
        frame %= pingpong_duration;
        if (frame < 0) {
            frame += pingpong_duration;
        }
        if (frame == 0) {
            frame = pingpong_duration;
        }
        if (frame > duration) {
            frame = (duration * 2) - frame;
        }
    }
    frame += offset;
    return frame;
